[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div style="height: 0; width: 0; margin: 0; padding: 0; border: none; overflow: hidden; line-height: 0; font-size: 0;"></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "HTML Personalizado", "fieldtype": "HTML", "options": "<div class="pdf-container">

    {% set es_volumen = (doc.custom_tipo_formato == "Volumen") %}

    <table class="info-table">
        <tr>
            <td class="client-section">
                <div class="info-line">
                    <strong>Cliente:</strong> {{ doc.customer_name or doc.customer }}
                </div>

                {% if doc.customer_address %}
                    {% set customer_address = frappe.get_doc("Address", doc.customer_address) %}
                    <div class="client-address">
                        <strong>Dirección de Entrega:</strong>
                        {% if customer_address.address_line1 %}
                            <div class="address-line">{{ customer_address.address_line1 }}</div>
                        {% endif %}
                        {% if customer_address.address_line2 %}
                            <div class="address-line">{{ customer_address.address_line2 }}</div>
                        {% endif %}
                        <div class="address-line">
                            {% if customer_address.city %}{{ customer_address.city }}{% endif %}
                            {% if customer_address.state and customer_address.city %}, {% endif %}
                            {% if customer_address.state %}{{ customer_address.state }}{% endif %}
                        </div>
                        <div class="address-line">
                            {% if customer_address.pincode %}C.P. {{ customer_address.pincode }}{% endif %}
                            {% if customer_address.country and customer_address.pincode %}, {% endif %}
                            {% if customer_address.country %}{{ customer_address.country }}{% endif %}
                        </div>
                    </div>
                {% endif %}

                {% if doc.contact_display %}
                    <div class="info-line"><strong>Contacto:</strong> {{ doc.contact_display }}</div>
                {% endif %}
            </td>

            <td class="quote-details">
                <span class="section-title">Cotización</span>
                <div class="info-line"><strong>Folio:</strong> {{ doc.name }}</div>
                <div class="info-line">
                    <strong>Válida hasta:</strong> {{ doc.get_formatted("valid_till") or frappe.format_date(doc.valid_till) }}
                </div>
                {% if doc.currency %}
                    <div class="info-line"><strong>Moneda:</strong> {{ doc.currency }}</div>
                {% endif %}
                {% if es_volumen %}
                     <div class="info-line" style="margin-top:5px; color:#FF6B15; font-weight:bold;">COTIZACIÓN POR VOLUMEN</div>
                {% endif %}
            </td>
        </tr>
    </table>

    {% if es_volumen %}
        {# Obtener todas las reglas de precios del primer item para determinar las columnas #}
        {% set primer_item = doc.items[0] if doc.items else None %}
        {% set columnas_precios = [] %}

        {% if primer_item %}
            {% set rules_base = frappe.get_all("Pricing Rule", 
                filters={
                    "item_code": primer_item.item_code, 
                    "disable": 0,
                    "selling": 1,
                    "min_qty": [">", 0]
                }, 
                fields=["min_qty", "max_qty", "apply_discount_on", "rate", "discount_percentage", "discount_amount", "for_price_list"], 
                order_by="min_qty asc") 
            %}

            {# Construir columnas dinámicas #}
            {% for rule in rules_base %}
                {% if rule.max_qty and rule.max_qty > 0 %}
                    {% set _ = columnas_precios.append({
                        "titulo": rule.min_qty|int|string + " - " + rule.max_qty|int|string + " pzas",
                        "min_qty": rule.min_qty,
                        "max_qty": rule.max_qty,
                        "indice": loop.index0
                    }) %}
                {% else %}
                    {% set _ = columnas_precios.append({
                        "titulo": rule.min_qty|int|string + "+ pzas",
                        "min_qty": rule.min_qty,
                        "max_qty": rule.max_qty,
                        "indice": loop.index0
                    }) %}
                {% endif %}
            {% endfor %}
        {% endif %}

        {# Calcular ancho de columnas dinámicamente #}
        {% set num_columnas = columnas_precios|length %}
        {% set ancho_columnas_precio = (60 / num_columnas)|int if num_columnas > 0 else 20 %}
    {% endif %}

    <table class="table items-table">
        <thead>
            <tr>
                <th class="text-center" width="5%">#</th>
                <th class="text-center" width="10%">Img</th>

                <th width="{% if es_volumen %}25%{% else %}25%{% endif %}">Artículo</th>

                {% if not es_volumen %}
                    <th width="25%">Descripción</th>

                    <th class="text-center" width="5%">Cant.</th> 
                    <th class="text-right" width="15%">P. Unitario</th>
                    <th class="text-right" width="15%">Importe</th>

                {% else %}
                    {# Generar columnas dinámicas para volumen #}
                    {% for columna in columnas_precios %}
                        <th class="text-center bg-volumen" width="{{ ancho_columnas_precio }}%">
                            {{ columna.titulo }}
                        </th>
                    {% endfor %}
                {% endif %}
            </tr>
        </thead>
        <tbody>
            {% for row in doc.items %}
            <tr>
                <td class="text-center">{{ row.idx }}</td>
                <td class="text-center item-image-cell">
                    {% if row.image %}
                        <img src="{{ row.image }}" alt="Img" class="item-image" />
                    {% else %}
                        -
                    {% endif %}
                </td>

                <td>
                    <strong class="item-title">{{ row.item_name or row.item_code }}</strong>

                    {% if row.item_code %}
                        <div class="item-code"><strong>Código:</strong> {{ row.item_code }}</div>
                    {% endif %}

                    {% if row.mx_product_service_key %}
                        <div class="item-fiscal-code"><strong>SAT:</strong> {{ row.mx_product_service_key }}</div>
                    {% endif %}

                    <div style="font-size:9px; color:#555; margin-top:2px;">
                        <strong>U.M.:</strong> {{ row.uom or row.stock_uom or "PZ" }}
                    </div>
                </td>

                {% if not es_volumen %}
                    <td>
                        <div class="item-description">{{ row.description }}</div>
                    </td>

                    <td class="text-center">
                        {{ row.qty }}
                    </td>

                    <td class="text-right">
                        {{ row.get_formatted("rate", doc) or "{:,.2f}".format(row.rate) }}
                    </td>
                    <td class="text-right">
                        <strong>{{ row.get_formatted("amount", doc) or "{:,.2f}".format(row.amount) }}</strong>
                    </td>

                {% else %}
                    {# Obtener reglas de precios para este item específico #}
                    {# Incluimos for_price_list para los modos de descuento que lo necesitan #}
                    {% set rules = frappe.get_all("Pricing Rule", 
                        filters={
                            "item_code": row.item_code, 
                            "disable": 0,
                            "selling": 1,
                            "min_qty": [">", 0]
                        }, 
                        fields=["min_qty", "max_qty", "apply_discount_on", "rate", "discount_percentage", "discount_amount", "for_price_list"], 
                        order_by="min_qty asc") 
                    %}

                    {# Iterar columnas por indice posicional — mismo orden que rules (min_qty asc) #}
                    {% for columna in columnas_precios %}
                        <td class="text-center volume-cell">
                            {% for rule in rules %}{% if loop.index0 == columna.indice %}

                                {# Detectar tipo por el campo que tenga valor, sin depender del string apply_discount_on #}
                                {% if rule.rate and rule.rate > 0 and rule.apply_discount_on == "Rate" %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(rule.rate) }}

                                {% elif rule.discount_percentage and rule.discount_percentage > 0 %}
                                    {% set item_prices = frappe.get_all("Item Price",
                                        filters={"item_code": row.item_code, "price_list": rule.for_price_list, "selling": 1},
                                        fields=["price_list_rate"], limit=1) if rule.for_price_list else [] %}
                                    {% set precio_base = item_prices[0].price_list_rate if item_prices else (row.price_list_rate or row.rate) %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(precio_base * (1 - rule.discount_percentage / 100)) }}
                                    <div style="font-size:8px; color:#888;">({{ "{:.0f}".format(rule.discount_percentage) }}% dto.)</div>

                                {% elif rule.discount_amount and rule.discount_amount > 0 %}
                                    {% set item_prices = frappe.get_all("Item Price",
                                        filters={"item_code": row.item_code, "price_list": rule.for_price_list, "selling": 1},
                                        fields=["price_list_rate"], limit=1) if rule.for_price_list else [] %}
                                    {% set precio_base = item_prices[0].price_list_rate if item_prices else (row.price_list_rate or row.rate) %}
                                    {% set precio_final = precio_base - rule.discount_amount %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(precio_final if precio_final > 0 else 0) }}
                                    <div style="font-size:8px; color:#888;">(-{{ doc.currency }} {{ "{:,.2f}".format(rule.discount_amount) }})</div>

                                {% elif rule.rate and rule.rate > 0 %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(rule.rate) }}

                                {% else %}
                                    -
                                {% endif %}

                            {% endif %}{% endfor %}
                        </td>
                    {% endfor %}
                {% endif %}
            </tr>
            {% endfor %}
        </tbody>
    </table>

    {% if not es_volumen %}
    <div class="totals-section">
        <table class="totals-table">
            <tr>
                <td class="total-label">Subtotal:</td>
                <td class="total-value">
                    {{ doc.get_formatted("base_total") or "{:,.2f}".format(doc.base_total) }}
                </td>
            </tr>
            {% for tax in doc.taxes %}
            <tr>
                <td class="total-label">{{ tax.description or tax.account_head }}</td>
                <td class="total-value">
                    {{ tax.get_formatted("tax_amount", doc) or "{:,.2f}".format(tax.tax_amount) }}
                </td>
            </tr>
            {% endfor %}

            <tr class="grand-total-row">
                <td class="total-label big-label">TOTAL:</td>
                <td class="total-value big-value">
                    {{ doc.get_formatted("grand_total") or "{:,.2f}".format(doc.grand_total) }}
                </td>
            </tr>
        </table>
        <div style="clear: both;"></div>
    </div>
    {% endif %}

    {% if doc.payment_schedule and not es_volumen %}
    <div class="payment-terms">
        <h4 class="payment-terms-title">Términos de Pago</h4>
        <table class="table payment-table">
            <thead>
                <tr>
                    <th width="50%">Plazo de pago</th>
                    <th class="text-center" width="10%">%</th>
                    <th class="text-center" width="20%">Vencimiento</th>
                    <th class="text-right" width="20%">Importe</th>
                </tr>
            </thead>
            <tbody>
                {% for term in doc.payment_schedule %}
                <tr>
                    <td>{{ term.payment_term }}</td>

                    <td class="text-center">
                        {{ "{:,.2f}".format(term.invoice_portion or 0) }}%
                    </td>

                    <td class="text-center">
                        {{ frappe.format_date(term.due_date) if term.due_date else "-" }}
                    </td>
                    <td class="text-right">
                        <strong>{{ doc.currency }} {{ "{:,.2f}".format(term.payment_amount or 0) }}</strong>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
    {% endif %}

    {% if doc.terms %}
    <div class="terms">
        <span class="terms-title">Términos y Condiciones:</span>
        <div class="terms-content">{{ doc.terms }}</div>
    </div>
    {% endif %}


    <div class="pdf-footer">
        <hr class="divider" />
        <p>Gracias por su preferencia.</p>
    </div>

</div>"}]
